window.TADABBUR_HIJR = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الحِجر (١٥)، سورةٌ مكّيّةٌ في حفظِ الله للقرآن، وقصصِ الأنبياء (إبراهيم، لوط، أصحاب الحِجر)، وتسليةِ النبيِّ ﷺ. تُفتتَح بـ«الر». كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":15,"name":"الحجر","total_ayahs":99,"audio":[],"passages":[{"title":"الكتابُ المبين، وندمُ الكافرين، وتركُهم في غفلتهم","range":[1,3],"theme":"عظمةُ القرآن، وتمنّي الكفارِ الإسلامَ يوم القيامة، وخطرُ الانشغالِ بالدنيا","verses":[{"n":1,"reflection":{"text":"«الر تلك آيات الكتاب وقرآن مبين» — افتُتحت السورةُ بالحروفِ المقطّعة؛ تلك الآياتُ العاليةُ آياتُ الكتابِ العظيمِ وقرآنٍ مبينٍ واضحٍ في لفظه ومعناه، يبيّن الحقَّ من الباطل؛ ففي هذا تعظيمُ القرآنِ ووصفُه بالبيان؛ فعظّم القرآنَ واطلب فيه البيانَ والهدى.","source":"تفسير السعدي","grade":"ma'thur"},"names":["مبين"],"heart_state":{"text":"تعظيمُ القرآنِ وطلبُ البيانِ فيه."},"action":{"text":"عظّم القرآنَ الكتابَ المبين، واطلب فيه بيانَ الحقّ وهداه، فهو يفصل الحقَّ من الباطلِ لمن تدبّره."}},{"n":2,"reflection":{"text":"«ربما يود الذين كفروا لو كانوا مسلمين» — كثيرًا ما يتمنّى الكفارُ يوم القيامةِ (أو عند رؤيةِ عاقبةِ المسلمين) لو كانوا مسلمين في الدنيا، حين لا ينفع التمنّي؛ ففي هذا أنّ الكافرَ يندم حين لا ينفع الندم؛ فبادر بالإسلامِ والطاعةِ في الدنيا قبل يومٍ يتمنّى فيه المفرّطون لو أطاعوا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإسلامِ والطاعةِ قبل يومِ الندمِ الذي لا ينفع."},"action":{"text":"بادر بالإيمانِ والعملِ الصالحِ الآن، قبل يومٍ يتمنّى فيه الكافرون لو كانوا مسلمين حين لا ينفع التمنّي."}},{"n":3,"reflection":{"text":"«ذرهم يأكلوا ويتمتعوا ويلههم الأمل فسوف يعلمون» — دعهم يا محمد يأكلوا كالأنعامِ ويتمتّعوا بالدنيا ويشغلهم طولُ الأملِ عن الآخرة، فسوف يعلمون عاقبةَ غفلتهم حين يرون العذاب؛ ففي هذا وعيدٌ للغافلين، وأنّ الانشغالَ بالأكلِ والتمتّعِ وطولِ الأملِ يُنسي الآخرة؛ فاحذر أن يُلهيك الأملُ والتمتّعُ عن الاستعدادِ للآخرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يُلهيَ الأملُ والتمتّعُ عن الاستعدادِ للآخرة."},"action":{"text":"لا تدع طولَ الأملِ والانشغالَ بملذّاتِ الدنيا يُنسيك الآخرة، واقصر أملك واعمل لما بعد الموت قبل فواتِ الأوان."}}]},{"title":"أنّ لكلِّ أمّةٍ أجلًا لا يتقدّم ولا يتأخّر","range":[4,5],"theme":"أنّ إهلاكَ الأممِ بأجلٍ مكتوب، وأنّ الآجالَ بيدِ الله","verses":[{"n":4,"reflection":{"text":"«وما أهلكنا من قرية إلا ولها كتاب معلوم» — وما أهلكنا قريةً من القرى المكذّبةِ إلا ولها أجلٌ مكتوبٌ معلومٌ عند الله لا تتجاوزه؛ ففي هذا أنّ إهلاكَ الأممِ بتقديرٍ وحكمة، وأنّ لكلِّ شيءٍ أجلًا؛ فلا تستعجل عقوبةَ الظالمين، فلكلِّ أمّةٍ أجلٌ مقدّرٌ عند الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمةِ الله في آجالِ الأمم، وتركُ الاستعجال."},"action":{"text":"سلّم لحكمةِ الله في تقديرِ آجالِ الأممِ والأشخاص، ولا تستعجل عقوبةَ الظالمين، فلكلِّ شيءٍ أجلٌ معلوم."}},{"n":5,"reflection":{"text":"«ما تسبق من أمة أجلها وما يستأخرون» — ما تتقدّم أمّةٌ عن أجلها المضروبِ لها ولا تتأخّر عنه لحظة، فالآجالُ محدّدةٌ لا تتغيّر؛ ففي هذا أنّ الأمورَ بتقديرِ الله، وأنّ الأجلَ لا يُستعجَل ولا يُؤخَّر؛ فاطمئن إلى تقديرِ الله، واعمل في أجلك قبل أن ينقضي، فلا استقدامَ فيه ولا استئخار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى تقديرِ الله للآجال، والعملُ قبل انقضائها."},"action":{"text":"اطمئن إلى أنّ الآجالَ بيدِ الله لا تتقدّم ولا تتأخّر، واغتنم أجلك بالعملِ الصالحِ قبل أن ينقضي."}}]},{"title":"اتّهامُ النبيِّ بالجنون، وطلبُ الملائكة","range":[6,8],"theme":"استهزاءُ الكفارِ بالنبيِّ ﷺ، وأنّ نزولَ الملائكةِ بالحقِّ لا بالاقتراح","verses":[{"n":6,"reflection":{"text":"«وقالوا يا أيها الذي نزل عليه الذكر إنك لمجنون» — وقال الكفارُ للنبيِّ ﷺ استهزاءً: يا من يزعم أنّ الذكرَ (القرآن) نزل عليه، إنك لمجنون بدعواك النبوّة! فوصفوا أعقلَ الخلقِ بالجنون؛ ففي هذا أنّ المبطلين يرمون أهلَ الحقِّ بأقبحِ الصفات؛ فلا يحزنك أن يرميك أهلُ الباطلِ بالباطل، فقد رموا أنبياءهم به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على أذى المبطلين ورميهم بالباطل."},"action":{"text":"لا يحزنك أن يصفك أهلُ الباطلِ بما ليس فيك، فقد رموا الأنبياءَ بالجنونِ والسحر، والزم الحقَّ واصبر على أذاهم."}},{"n":7,"reflection":{"text":"«لو ما تأتينا بالملائكة إن كنت من الصادقين» — قالوا تعنّتًا: هلّا تأتينا بالملائكةِ يشهدون لك بالصدقِ أو يعذّبوننا إن كنت صادقًا في نبوّتك؟ فطلبوا ما لا يكون إلا للعذاب؛ ففي هذا أنّ اقتراحَ الآياتِ تعنّتٌ لا يُراد به الهدى؛ فلا تعلّق إيمانك على مقترحاتٍ تعنّتيّة، بل آمن بالبراهينِ القائمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ اقتراحِ الآياتِ تعنّتًا، والإيمانُ بالبراهينِ القائمة."},"action":{"text":"لا تطلب من الحقِّ آياتٍ تقترحها تعنّتًا، بل آمن بالبراهينِ القائمةِ التي بلغتك، فاقتراحُ الآياتِ عنادٌ لا هدى."}},{"n":8,"reflection":{"text":"«ما ننزل الملائكة إلا بالحق وما كانوا إذا منظرين» — ما نُنزّل الملائكةَ إلا بالحقِّ (بالوحيِ أو بالعذابِ عند حلولِ الأجل)، وما كانوا حينئذٍ (لو نزلت الملائكةُ بالعذاب) مُمهَلين بل يُهلكون فورًا؛ ففي هذا أنّ نزولَ الملائكةِ للعذابِ يعني الهلاكَ لا الإمهال؛ فلا تستعجل ما فيه هلاكك، واغتنم مهلةَ الإمهالِ بالتوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ مهلةِ الإمهال، وعدمُ استعجالِ ما فيه الهلاك."},"action":{"text":"اغتنم مهلةَ الله لك بالتوبةِ والعمل، ولا تستعجل نزولَ ما فيه هلاكك، فنزولُ الملائكةِ بالعذابِ لا إمهالَ بعده."}}]},{"title":"حفظُ الله للقرآن","range":[9,9],"theme":"تكفّلُ الله بحفظِ القرآنِ من التبديلِ والتحريفِ إلى يومِ القيامة","verses":[{"n":9,"reflection":{"text":"«إنا نحن نزلنا الذكر وإنا له لحافظون» — إنا نحن نزّلنا القرآنَ (الذكر) على محمدٍ ﷺ، وإنا له لحافظون من الزيادةِ والنقصِ والتحريفِ والتبديل إلى يومِ القيامة؛ ففي هذا أنّ حفظَ القرآنِ ضمانةٌ إلهيّةٌ لا تتخلّف، وأنه باقٍ محفوظٌ لا كالكتبِ قبله التي وُكل حفظُها إلى الناسِ فحُرّفت؛ فاطمئن إلى أنّ كتابك محفوظٌ بحفظِ الله، فتمسّك به واثقًا بأنه لن يُحرَّف ولن يضيع.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إنا له لحافظون"],"heart_state":{"text":"الاطمئنانُ إلى حفظِ الله للقرآن، والتمسّكُ به واثقًا."},"action":{"text":"اطمئن إلى أنّ القرآنَ محفوظٌ بحفظِ الله من كلِّ تحريفٍ إلى يوم القيامة، فتمسّك به واثقًا بأنه الحقُّ الباقي."}}]},{"title":"سنّةُ الاستهزاءِ بالرسل، وسلوكُ التكذيبِ في قلوبِ المجرمين","range":[10,13],"theme":"أنّ الاستهزاءَ بالرسلِ سنّةٌ ماضية، وأنّ الإجرامَ يمنع الإيمان","verses":[{"n":10,"reflection":{"text":"«ولقد أرسلنا من قبلك في شيع الأولين» — ولقد أرسلنا رسلًا من قبلك يا محمد في فرقِ الأممِ وطوائفهم الأوّلين؛ ففي هذا تسليةٌ للنبيِّ بأنّ إرسالَ الرسلِ سنّةٌ ماضية، وأنه ليس ببدعٍ من الرسل؛ فاقتدِ بمن سبقك من الرسلِ في الصبرِ والتبليغ، ولا تستوحش من قلّةِ المستجيبين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالرسلِ السابقين في الصبرِ والتبليغ."},"action":{"text":"اقتدِ بالأنبياءِ السابقين في صبرهم على الدعوةِ وتبليغهم، ولا تستوحش من إعراضِ الناس، فذاك سبيلُ الرسلِ قبلك."}},{"n":11,"reflection":{"text":"«وما يأتيهم من رسول إلا كانوا به يستهزئون» — وما يأتي تلك الأممَ رسولٌ إلا استهزؤوا به وسخروا منه؛ ففي هذا أنّ الاستهزاءَ بالرسلِ سنّةُ المكذّبين في كلِّ زمان؛ فلا يحزنك استهزاءُ المستهزئين بالحقّ، فقد استُهزئ بالرسلِ جميعًا، والعاقبةُ لهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على استهزاءِ المكذّبين، فهو سنّةٌ ماضيةٌ مع الرسل."},"action":{"text":"لا يحزنك استهزاءُ المبطلين بالحقِّ وأهله، فقد استُهزئ بالرسلِ جميعًا، واثبت على الحقّ، فالعاقبةُ للمتقين."}},{"n":12,"reflection":{"text":"«كذلك نسلكه في قلوب المجرمين» — كذلك نُدخل التكذيبَ والاستهزاءَ في قلوبِ المجرمين المصرّين على الإجرام (جزاءً لهم على إعراضهم)؛ ففي هذا أنّ الإصرارَ على الإجرامِ يورث القلبَ التكذيبَ فلا يقبل الحقّ؛ فاحذر الإصرارَ على المعصيةِ فيُسلَك في قلبك التكذيب، وطهّر قلبك بالتوبةِ ليقبل الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإصرارِ على الإجرامِ الذي يورث القلبَ التكذيب."},"action":{"text":"احذر الإصرارَ على المعاصي والإجرام، فإنه يُدخل في القلبِ التكذيبَ والإعراض، وطهّر قلبك بالتوبةِ ليقبل الحقّ."}},{"n":13,"reflection":{"text":"«لا يؤمنون به وقد خلت سنة الأولين» — لا يؤمن هؤلاء المجرمون بالقرآنِ والرسولِ لإصرارهم، وقد مضت سنّةُ الله في الأوّلين بإهلاكِ المكذّبين، فسيلحقهم مثلُ ما لحق أولئك؛ ففي هذا أنّ سنّةَ الله في المكذّبين واحدةٌ لا تتبدّل؛ فاعتبر بسنّةِ الله في المكذّبين قبلك، ولا تسلك سبيلهم فينالك ما نالهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بسنّةِ الله في المكذّبين، وعدمُ سلوكِ سبيلهم."},"action":{"text":"اعتبر بسنّةِ الله الماضيةِ في إهلاكِ المكذّبين، ولا تسلك سبيلهم في الإصرارِ على التكذيب، فسنّتُه لا تتبدّل."}}]},{"title":"عنادُ المكذّبين ولو رأوا الآيات","range":[14,15],"theme":"أنّ المعاندَ لا تنفعه الآياتُ ولو عاينها، بل يؤوّلها بالسحر","verses":[{"n":14,"reflection":{"text":"«ولو فتحنا عليهم بابا من السماء فظلوا فيه يعرجون» — ولو فتحنا على هؤلاء المعاندين بابًا من السماءِ فصاروا يصعدون فيه ويشاهدون الملكوتَ عيانًا؛ ففي هذا أنّ المعاندَ لا تنفعه أعظمُ الآيات؛ فاعلم أنّ العنادَ يحجب عن الإيمانِ ولو عاين العبدُ أعظمَ البراهين، فاطلب الهدى بقلبٍ منقاد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ العنادَ يحجب عن الإيمانِ ولو عاين العبدُ الآيات."},"action":{"text":"اطلب الهدى بقلبٍ منقادٍ للحقّ، فالمعاندُ لا تنفعه الآياتُ ولو عاينها، فلا تجعل عنادك حاجبًا بينك وبين الحقّ."}},{"n":15,"reflection":{"text":"«لقالوا إنما سكرت أبصارنا بل نحن قوم مسحورون» — لقالوا مع تلك المعاينة: إنما غُطّيت أبصارُنا وحُبست عن الإبصار، بل نحن قومٌ سُحرنا فخُيّل إلينا ذلك! فيؤوّلون الحقَّ الواضحَ بالسحرِ فرارًا من الإذعان؛ ففي هذا أنّ المعاندَ يجحد ما رأى بعينه؛ فاحذر أن يبلغ بك العنادُ أن تجحد الحقَّ الذي تراه، واقبل الحقَّ إذا تبيّن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العنادِ الذي يجحد الحقَّ المرئيَّ بالعين."},"action":{"text":"احذر أن يبلغ بك العنادُ أن تؤوّل الحقَّ الواضحَ أو تجحد ما تراه بعينك، بل اقبل الحقَّ إذا تبيّن ولو خالف هواك."}}]},{"title":"بروجُ السماءِ وحفظُها","range":[16,18],"theme":"آياتُ الله في تزيينِ السماءِ وحفظِها من الشياطين","verses":[{"n":16,"reflection":{"text":"«ولقد جعلنا في السماء بروجا وزيناها للناظرين» — ولقد جعلنا في السماءِ منازلَ للكواكبِ والنجومِ العظيمة، وزيّنّاها بالنجومِ المضيئةِ للناظرين المتأمّلين؛ ففي هذا آيةٌ على قدرةِ الله وجمالِ صنعه؛ فتأمّل زينةَ السماءِ ونجومها، لتستدلّ بجمالِ الصنعِ على عظمةِ الصانع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في زينةِ السماءِ للاستدلالِ على عظمةِ الخالق."},"action":{"text":"تأمّل جمالَ السماءِ وزينتها بالنجوم، واستدلّ بحسنِ صنعِ الله على عظمته، واشكره على جمالِ ما خلق."}},{"n":17,"reflection":{"text":"«وحفظناها من كل شيطان رجيم» — وحفظنا السماءَ من كلِّ شيطانٍ مطرودٍ من رحمةِ الله أن يصعد إليها ويسترق أخبارها؛ ففي هذا حفظُ الله للسماءِ ووحيه من تلاعبِ الشياطين؛ فاطمئن إلى أنّ الله يحفظ وحيه وسماءه، ويحمي دينه من كيدِ الشياطين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى حفظِ الله لوحيه وسمائه من الشياطين."},"action":{"text":"اطمئن إلى أنّ الله يحفظ سماءه ووحيه من كلِّ شيطانٍ رجيم، فدينه محفوظٌ محميٌّ من كيدِ الشياطين."}},{"n":18,"reflection":{"text":"«إلا من استرق السمع فأتبعه شهاب مبين» — إلا من حاول من الشياطينِ أن يسترق شيئًا من أخبارِ الملأ الأعلى، فيتبعه شهابٌ من النجومِ ظاهرٌ يحرقه أو يطرده؛ ففي هذا حراسةُ الله للسماءِ حراسةً محكمة؛ فاعلم أنّ الله يحمي غيبه ووحيه، فلا سبيلَ للشياطينِ إلى تحريفه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يحرس غيبه ووحيه حراسةً محكمة."},"action":{"text":"أيقن أنّ الله يحرس السماءَ ووحيه من استراقِ الشياطين بالشهب، فغيبه ووحيه محفوظان لا يبلغهما كيدُ الشيطان."}}]},{"title":"مدُّ الأرضِ وخزائنُ الرزق","range":[19,21],"theme":"آياتُ الله في الأرضِ وأرزاقها، وأنّ خزائنَ كلِّ شيءٍ عنده","verses":[{"n":19,"reflection":{"text":"«والأرض مددناها وألقينا فيها رواسي وأنبتنا فيها من كل شيء موزون» — والأرضَ بسطناها ووسّعناها لتستقرّوا عليها، وألقينا فيها جبالًا راسياتٍ تثبّتها، وأنبتنا فيها من كلِّ شيءٍ مقدّرٍ موزونٍ بالحكمةِ (كلٌّ بقدره ونفعه)؛ ففي هذا أنّ خلقَ الأرضِ ونباتها بحكمةٍ وتقدير؛ فتأمّل حكمةَ الله في خلقِ الأرضِ ونباتها الموزون، واشكره على تمهيدها لك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في حكمةِ الله في خلقِ الأرضِ ونباتها الموزون."},"action":{"text":"تأمّل كيف مدّ الله الأرضَ وأرساها بالجبالِ وأنبت فيها كلَّ شيءٍ بقدرٍ وحكمة، واشكره على تمهيدها ورزقها."}},{"n":20,"reflection":{"text":"«وجعلنا لكم فيها معايش ومن لستم له برازقين» — وجعلنا لكم في الأرضِ أسبابَ المعيشةِ من الطعامِ والشرابِ وسائرِ المنافع، وجعلنا فيها من الدوابِّ والخدمِ وغيرهم ممّن لستم أنتم رازقيهم بل الله رازقهم؛ ففي هذا أنّ الله رازقُ الجميع، وأنّ أسبابَ العيشِ منّةٌ منه؛ فاشكر الله على معايشك، واعلم أنه رازقك ورازقُ من تعول، فلا تحمل همَّ الرزق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على المعايش، واليقينُ بأنه الرازقُ للجميع."},"action":{"text":"اشكر الله على أسبابِ معيشتك، واعلم أنه رازقك ورازقُ من تعول ومن لا تقدر على رزقه، فلا تحمل همَّ الرزق."}},{"n":21,"reflection":{"text":"«وإن من شيء إلا عندنا خزائنه وما ننزله إلا بقدر معلوم» — وما من شيءٍ ينتفع به العبادُ إلا وعندنا خزائنه ومفاتيحه، وما نُنزّله وننشره إلا بمقدارٍ محدّدٍ معلومٍ بحكمتنا (لا بخلًا بل حكمة)؛ ففي هذا أنّ خزائنَ كلِّ شيءٍ بيدِ الله، وأنه يعطي بقدرٍ وحكمة؛ فاطلب حاجاتك من الله الذي بيده خزائنُ كلِّ شيء، واطمئن إلى أنّ عطاءه بقدرٍ وحكمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["عنده خزائنه"],"heart_state":{"text":"طلبُ الحاجاتِ من الله الذي بيده خزائنُ كلِّ شيء."},"action":{"text":"اطلب حاجاتك من الله الذي عنده خزائنُ كلِّ شيء، واطمئن إلى أنّ عطاءه بقدرٍ وحكمةٍ لا بخلٍ ولا عجز."}}]},{"title":"الرياحُ والماء، وأنّ الله يحيي ويميت","range":[22,23],"theme":"آياتُ الله في الرياحِ والمطر، وتفرّدُه بالإحياءِ والإماتةِ والوراثة","verses":[{"n":22,"reflection":{"text":"«وأرسلنا الرياح لواقح فأنزلنا من السماء ماء فأسقيناكموه وما أنتم له بخازنين» — وأرسلنا الرياحَ حواملَ للسحابِ ملقحاتٍ له لينزل المطر، فأنزلنا من السماءِ ماءً عذبًا فأسقيناكموه وسقينا أنعامكم وأرضكم، وما أنتم بقادرين على خزنه وحفظه لو شئنا لأذهبناه؛ ففي هذا نعمةُ الله في الرياحِ والمطرِ وحفظِه للماءِ في الأرض؛ فاشكر الله على نعمةِ الماء، فهو الذي أنزله وحفظه لك، ولا قدرةَ لك على ذلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الماء، واليقينُ بأنّ حفظه بيدِ الله وحده."},"action":{"text":"اشكر الله على نعمةِ الماءِ العذبِ الذي أنزله وحفظه لك، فلا قدرةَ لك على خزنه، فهو من محضِ فضله ورحمته."}},{"n":23,"reflection":{"text":"«وإنا لنحن نحيي ونميت ونحن الوارثون» — وإنا لنحن نحيي الخلقَ من العدمِ ونميتهم عند آجالهم، ونحن الباقون بعد فناءِ الخلقِ نرث الأرضَ ومن عليها؛ ففي هذا تفرّدُ الله بالإحياءِ والإماتةِ والبقاء، وأنّ كلَّ ما سواه فانٍ؛ فاعمل لمن بيده حياتك وموتك، ولا تعلّق قلبك بفانٍ، فالله وحده الباقي الوارث.","source":"تفسير السعدي","grade":"ma'thur"},"names":["نحيي ونميت","الوارثون"],"heart_state":{"text":"العملُ لمن بيده الإحياءُ والإماتة، وعدمُ التعلّقِ بفانٍ."},"action":{"text":"اعمل لله الذي يحييك ويميتك وهو الباقي بعد فناءِ الخلق، ولا تعلّق قلبك بمخلوقٍ فانٍ، فكلُّ شيءٍ إلى زوالٍ إلا وجهه."}}]},{"title":"إحاطةُ علمِ الله بالأوّلين والآخرين، وحشرُهم","range":[24,25],"theme":"أنّ الله يعلم من مضى ومن سيأتي، وأنه يحشرهم بحكمته","verses":[{"n":24,"reflection":{"text":"«ولقد علمنا المستقدمين منكم ولقد علمنا المستأخرين» — ولقد علمنا من تقدّم من الخلقِ ومات، ومن تأخّر ولم يُخلَق بعد (أو المتقدّمين في صفوفِ الطاعةِ والمتأخّرين عنها)، فعلمُنا محيطٌ بالجميع؛ ففي هذا إحاطةُ علمِ الله بكلِّ الخلقِ ماضيهم وآتيهم؛ فراقب الله العليمَ بك وبكلِّ الخلق، وسابق إلى الخيرِ لتكون من المستقدمين إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله المحيطِ علمُه، والمسابقةُ إلى الخير."},"action":{"text":"راقب الله الذي يعلم الأوّلين والآخرين، وسابق إلى الطاعةِ والخير لتكون من المتقدّمين إليها، فعلمُه محيطٌ بك."}},{"n":25,"reflection":{"text":"«وإن ربك هو يحشرهم إنه حكيم عليم» — وإنّ ربّك هو الذي يجمع الخلقَ كلَّهم يوم القيامةِ للحساب، إنه حكيمٌ في تدبيره وجزائه عليمٌ بأعمالهم وأحوالهم؛ ففي هذا أنّ الحشرَ حقٌّ بحكمةِ الله وعلمه، وأنّ الجزاءَ بالعدل؛ فاستعدّ ليومِ الحشرِ الذي يجمعك فيه ربّك الحكيمُ العليم، واعمل لذلك اليوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["حكيم","عليم"],"heart_state":{"text":"الاستعدادُ ليومِ الحشرِ، واليقينُ بحكمةِ الله وعلمه في الجزاء."},"action":{"text":"استعدّ ليومِ الحشرِ الذي يجمعك فيه ربّك، واعلم أنه حكيمٌ عليمٌ يجزي بالعدل، فأصلح عملك لذلك اليوم."}}]},{"title":"خلقُ الإنسانِ والجانّ","range":[26,27],"theme":"بيانُ أصلِ خلقِ الإنسانِ من طين، والجانِّ من نار","verses":[{"n":26,"reflection":{"text":"«ولقد خلقنا الإنسان من صلصال من حمإ مسنون» — ولقد خلقنا الإنسانَ (آدم) من طينٍ يابسٍ يُصوّت إذا نُقر (صلصال) من طينٍ أسودَ متغيّرٍ (حمإٍ مسنون)؛ ففي هذا بيانُ أصلِ الإنسانِ المتواضعِ من الطين، ليتذكّر ضعفه وأصله فلا يتكبّر؛ فتذكّر أصلك من طين، فلا يحملك ذلك على كبرٍ، بل على تواضعٍ وشكرٍ لمن رفعك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ أصلِ الخلقِ من الطينِ لدفعِ الكبرِ والتواضع."},"action":{"text":"تذكّر أنّ أصلك من طينٍ متواضع، فلا يحملك ذلك على كبرٍ، بل على تواضعٍ لله وشكرٍ له إذ كرّمك ورفعك."}},{"n":27,"reflection":{"text":"«والجان خلقناه من قبل من نار السموم» — والجانَّ (أصلَ الجنّ، أو إبليس) خلقناه من قبلِ خلقِ آدمَ من نارِ الحرِّ الشديدِ النافذة؛ ففي هذا بيانُ اختلافِ أصلِ الجنِّ عن الإنس، وأنّ اختلافَ الأصلِ لا يبرّر الكبر (كما تكبّر إبليس بأصله)؛ فلا تفاخر بأصلٍ أو جنس، فالكرامةُ بالتقوى لا بالأصل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الكرامةَ بالتقوى لا بالأصلِ أو الجنس."},"action":{"text":"لا تفاخر بأصلٍ أو جنسٍ أو نسب، فقد تكبّر إبليسُ بأصلِ خلقه فهلك، والكرامةُ عند الله بالتقوى والعملِ لا بالأصل."}}]},{"title":"خلقُ آدمَ وسجودُ الملائكةِ وإباءُ إبليس","range":[28,33],"theme":"تكريمُ الله لآدم، وطاعةُ الملائكة، وكبرُ إبليسَ واحتجاجُه بأصله","verses":[{"n":28,"reflection":{"text":"«وإذ قال ربك للملائكة إني خالق بشرا من صلصال من حمإ مسنون» — واذكر إذ قال ربّك للملائكة: إني خالقٌ بشرًا (آدم) من طينٍ يابسٍ من حمإٍ متغيّر؛ ففي هذا إعلامُ الله للملائكةِ بخلقِ آدمَ تمهيدًا لتكريمه؛ ففي هذا أنّ الله يهيّئ لأمره ويعلن حكمته؛ فتدبّر كيف مهّد الله لخلقِ آدمَ وتكريمه، واعلم أنّ لله في خلقه حكمةً بالغة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التدبّرُ في حكمةِ الله في خلقِ آدمَ وتكريمه."},"action":{"text":"تدبّر كيف أعلن الله للملائكةِ خلقَ آدمَ تمهيدًا لتكريمه، واعلم أنّ لله في كلِّ ما يخلق ويقدّر حكمةً بالغة."}},{"n":29,"reflection":{"text":"«فإذا سويته ونفخت فيه من روحي فقعوا له ساجدين» — فإذا أتممتُ خلقَ آدمَ وسوّيتُه ونفختُ فيه من روحي (روحًا خلقتُها وأضفتُها إليّ تشريفًا)، فاسجدوا له سجودَ تحيّةٍ وتكريمٍ (لا عبادة)؛ ففي هذا تكريمُ الله لآدمَ بأمرِ الملائكةِ بالسجودِ له، وشرفُ الروحِ التي فيه؛ فاعرف قدرَ ما كرّمك الله به من الروحِ والعقل، واستعمله في طاعته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ قدرِ تكريمِ الله للإنسانِ واستعمالُه في الطاعة."},"action":{"text":"اعرف قدرَ ما كرّمك الله به من الروحِ والعقل، فقد أمر الملائكةَ بالسجودِ لأبيك آدم، فاستعمل هذا التكريمَ في طاعته."}},{"n":30,"reflection":{"text":"«فسجد الملائكة كلهم أجمعون» — فسجد الملائكةُ كلُّهم جميعًا امتثالًا لأمرِ الله بلا تأخّرٍ ولا استثناء؛ ففي هذا كمالُ طاعةِ الملائكةِ وانقيادهم لأمرِ الله؛ فاقتدِ بالملائكةِ في المبادرةِ إلى امتثالِ أمرِ الله بلا تردّدٍ ولا تأخّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في المبادرةِ إلى امتثالِ أمرِ الله."},"action":{"text":"بادر إلى امتثالِ أمرِ الله بلا تردّدٍ ولا تأخّر، اقتداءً بالملائكةِ الذين سجدوا كلُّهم أجمعون طاعةً لأمره."}},{"n":31,"reflection":{"text":"«إلا إبليس أبى أن يكون مع الساجدين» — إلا إبليسَ امتنع واستكبر أن يكون مع الساجدين لآدم؛ ففي هذا أنّ الكِبرَ عن أمرِ الله أوّلُ معصيةٍ عُصي الله بها، وأنه سببُ الطردِ من رحمته؛ فاحذر الكِبرَ عن الطاعةِ فهو أصلُ البلاء، وأوّلُ ذنبٍ أهلك صاحبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ عن أمرِ الله، فهو أصلُ المعاصي."},"action":{"text":"احذر الكِبرَ عن أمرِ الله وطاعته، فهو أوّلُ ذنبٍ عُصي الله به وسببُ طردِ إبليس، فالزم التواضعَ والانقياد."}},{"n":32,"reflection":{"text":"«قال يا إبليس ما لك ألا تكون مع الساجدين» — قال الله لإبليسَ موبّخًا: يا إبليسُ ما الذي منعك أن تكون مع الساجدين لآدم؟ ففي هذا أنّ الله يسأل العاصيَ عن سببِ عصيانه إقامةً للحجّة؛ فحاسب نفسك عن أسبابِ تقصيرك في الطاعةِ قبل أن تُسأل، فلا عذرَ في تركِ أمرِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ عن أسبابِ التقصيرِ في الطاعة."},"action":{"text":"حاسب نفسك عن كلِّ تقصيرٍ في طاعةِ الله وابحث عن دوافعه، فلا عذرَ في تركِ أمرِ الله، وستُسأل عن ذلك."}},{"n":33,"reflection":{"text":"«قال لم أكن لأسجد لبشر خلقته من صلصال من حمإ مسنون» — قال إبليسُ متكبّرًا محتجًّا بأصله: ما كنت لأسجد لبشرٍ خلقتَه من طينٍ يابسٍ من حمإٍ متغيّر، فأنا خيرٌ منه إذ خُلقت من نار! ففي هذا أنّ الكِبرَ يحمل على ردِّ أمرِ الله بالقياسِ الفاسدِ والاحتجاجِ الباطل؛ فلا تعارض أمرَ الله برأيك وقياسك، فطاعةُ الله لا تُردّ باحتجاجٍ من هوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ معارضةِ أمرِ الله بالرأيِ والقياسِ الفاسد."},"action":{"text":"لا تعارض أمرَ الله وشرعه برأيك أو قياسك أو هواك كما فعل إبليس، بل انقد لأمره وسلّم، فطاعتُه لا تُردّ بحجّة."}}]},{"title":"طردُ إبليسَ وإمهالُه","range":[34,38],"theme":"عاقبةُ كبرِ إبليس بالطردِ واللعنة، وإمهالُه إلى الوقتِ المعلوم","verses":[{"n":34,"reflection":{"text":"«قال فاخرج منها فإنك رجيم» — قال الله لإبليس: فاخرج من الجنّةِ (أو من السماءِ ومنزلةِ الملائكة) فإنك مطرودٌ مرجومٌ باللعنة؛ ففي هذا أنّ الكِبرَ والعصيانَ سببُ الطردِ من رحمةِ الله ومنازلِ الكرامة؛ فاحذر الكِبرَ والمعصيةَ فعاقبتهما الطردُ والإبعاد، والزم التواضعَ والطاعةَ لتقرب من الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ والمعصيةِ فعاقبتهما الطردُ من الرحمة."},"action":{"text":"احذر الكِبرَ والعصيانَ فعاقبتهما الطردُ من رحمةِ الله كما طُرد إبليس، والزم التواضعَ والطاعةَ لتنال القرب."}},{"n":35,"reflection":{"text":"«وإن عليك اللعنة إلى يوم الدين» — وإنّ عليك يا إبليسُ الطردَ من رحمةِ الله واللعنةَ المستمرّةَ إلى يومِ الجزاء؛ ففي هذا أنّ عاقبةَ الإصرارِ على الكبرِ لعنةٌ دائمة؛ فاحذر أسبابَ اللعنة، والزم ما يقرّبك من رحمةِ الله لا ما يبعدك عنها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أسبابِ اللعنةِ والبعدِ عن رحمةِ الله."},"action":{"text":"احذر الكِبرَ والإصرارَ على المعصية، فهما سببُ اللعنةِ الدائمة، والزم أسبابَ رحمةِ الله وقربه."}},{"n":36,"reflection":{"text":"«قال رب فأنظرني إلى يوم يبعثون» — قال إبليسُ: ربِّ أمهلني وأخّر موتي إلى يومِ يُبعث الخلق (طمعًا في ألّا يموت)؛ ففي هذا حرصُ إبليسَ على البقاءِ للإغواء؛ ففي هذا أنّ عدوّك حريصٌ دائبٌ على إغوائك، فخذ حذرك منه، واستعذ بالله من شرّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من حرصِ الشيطانِ الدائبِ على الإغواء."},"action":{"text":"خذ حذرك من الشيطانِ الحريصِ على إغوائك، واستعذ بالله من شرّه دائمًا، فهو عدوٌّ دائبٌ لا يفتر عن كيدك."}},{"n":37,"reflection":{"text":"«قال فإنك من المنظرين» — قال الله: فإنك يا إبليسُ من المؤخَّرين المُمهَلين؛ ففي هذا أنّ الله أمهل إبليسَ ابتلاءً للعباد وامتحانًا؛ ففي هذا أنّ الإمهالَ في الدنيا امتحان، فاجعل مهلتك في طاعةِ الله لا في اتّباعِ عدوّك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّخاذُ مهلةِ العمرِ في الطاعةِ لا في اتّباعِ الشيطان."},"action":{"text":"اجعل مهلةَ عمرك في طاعةِ الله والاستعدادِ للقائه، لا في اتّباعِ الشيطانِ الذي أُمهل ليفتنك، فالإمهالُ امتحان."}},{"n":38,"reflection":{"text":"«إلى يوم الوقت المعلوم» — إلى يومِ الوقتِ المعلومِ عند الله (وهو النفخةُ الأولى التي يموت فيها الخلق، لا يومُ البعثِ الذي طلبه)؛ ففي هذا أنّ الله أعطى إبليسَ بعضَ ما طلب لا كلَّه بحكمته؛ ففي هذا أنّ الآجالَ والأوقاتَ بيدِ الله وحده بحكمته؛ فسلّم أمرك لله العالمِ بالأوقاتِ والآجال، فكلٌّ إلى أجلٍ معلومٍ عنده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في الآجالِ والأوقاتِ المعلومةِ عنده."},"action":{"text":"سلّم أمرك لله العالمِ بالآجالِ والأوقات، واعلم أنّ لكلِّ شيءٍ وقتًا معلومًا عنده بحكمته، فاعمل قبل انقضاء وقتك."}}]},{"title":"تهديدُ إبليسَ بالإغواء، وعصمةُ المخلَصين","range":[39,42],"theme":"عزمُ الشيطانِ على الإغواء، وأنّ المخلَصين في حرزِ الله لا سلطانَ له عليهم","verses":[{"n":39,"reflection":{"text":"«قال رب بما أغويتني لأزينن لهم في الأرض ولأغوينهم أجمعين» — قال إبليسُ: ربِّ بسببِ إغوائك لي (يحتجّ بالقدر) لأزيّننّ للناسِ المعاصيَ في الأرضِ حتى تحسن في أعينهم، ولأُضلّنّهم أجمعين؛ ففي هذا أنّ الشيطانَ يزيّن المعاصيَ ليوقع فيها، وأنّ من كيده تحسينَ القبيح؛ فاحذر تزيينَ الشيطانِ للمعصية، ولا تغترّ بحسنِ ظاهرِ ما حرّم الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تزيينِ الشيطانِ للمعاصي في القلب."},"action":{"text":"احذر أن يزيّن لك الشيطانُ المعصيةَ فتحسن في عينك، ولا تغترّ بحسنِ ظاهرِ ما حرّم الله، فتزيينُ القبيحِ من كيده."}},{"n":40,"reflection":{"text":"«إلا عبادك منهم المخلصين» — قال إبليسُ مستثنيًا: إلا عبادك الذين أخلصتهم لطاعتك واخترتهم، فلا سبيلَ لي إليهم؛ ففي هذا أنّ الإخلاصَ حرزٌ من كيدِ الشيطان، وأنّ المخلَصين في عصمةٍ من إغوائه؛ فأخلص عملك لله يعصمك من كيدِ الشيطان، فالإخلاصُ سياجُ القلب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["المخلصين"],"heart_state":{"text":"أنّ الإخلاصَ حرزٌ من كيدِ الشيطان وعصمةٌ منه."},"action":{"text":"أخلص عملك ونيّتك لله وحده، فالإخلاصُ حرزٌ يعصمك من كيدِ الشيطان، والمخلَصون لا سلطانَ له عليهم."}},{"n":41,"reflection":{"text":"«قال هذا صراط علي مستقيم» — قال الله: هذا (الإخلاصُ والعبوديّةُ الحقّة) طريقٌ مستقيمٌ عليّ رعايتُه وحفظُه، ومن سلكه أوصلته إليّ (أو: عليّ بيانه)؛ ففي هذا أنّ طريقَ العبوديّةِ الخالصةِ مستقيمٌ موصلٌ إلى الله، محفوظٌ برعايته؛ فالزم الصراطَ المستقيمَ من الإخلاصِ والطاعة، فهو الطريقُ الموصلُ إلى الله المحفوظُ برعايته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الصراطِ المستقيمِ الموصلِ إلى الله برعايته."},"action":{"text":"الزم صراطَ الإخلاصِ والعبوديّةِ لله، فهو الطريقُ المستقيمُ الموصلُ إليه، الذي تكفّل الله برعايةِ سالكيه."}},{"n":42,"reflection":{"text":"«إن عبادي ليس لك عليهم سلطان إلا من اتبعك من الغاوين» — إنّ عبادي المخلصين ليس لك يا إبليسُ عليهم تسلّطٌ وقهرٌ تحملهم به على المعصية، إلا من اتّبعك من الضالّين الذين أطاعوك باختيارهم؛ ففي هذا أنّ الشيطانَ لا يقهر أحدًا، وإنما يُغوي من استجاب له؛ فلا تتّبع الشيطانَ فتقع تحت سلطانه، واعتصم بطاعةِ الله يعصمك منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الشيطانَ لا يقهر أحدًا، وإنما يُغوي من استجاب له."},"action":{"text":"اعلم أنّ الشيطانَ لا سلطانَ له عليك إلا إن اتّبعته، فاعتصم بطاعةِ الله وإخلاصك، ولا تستجب لوسوسته فتقع تحت سلطانه."}}]},{"title":"جهنمُ موعدُ الغاوين","range":[43,44],"theme":"أنّ جهنمَ موعدُ من اتّبع الشيطان، ولها أبوابٌ بحسبِ الأعمال","verses":[{"n":43,"reflection":{"text":"«وإن جهنم لموعدهم أجمعين» — وإنّ جهنمَ لموعدُ إبليسَ وأتباعه من الغاوين جميعًا؛ ففي هذا أنّ عاقبةَ اتّباعِ الشيطانِ جهنم؛ فاحذر أن تكون من أتباعِ الشيطانِ الذين موعدهم النار، والزم طاعةَ الله لتكون من أهلِ الجنّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ الشيطانِ الذي موعدُ أتباعه جهنم."},"action":{"text":"احذر أن تتّبع الشيطانَ فتكون من الغاوين الذين موعدهم جهنم، والزم طاعةَ الله وإخلاصك لتنجو وتكون من أهلِ الجنّة."}},{"n":44,"reflection":{"text":"«لها سبعة أبواب لكل باب منهم جزء مقسوم» — لجهنمَ سبعةُ أبوابٍ (طبقاتٍ)، لكلِّ بابٍ منها نصيبٌ مقسومٌ من أتباعِ الشيطانِ بحسبِ أعمالهم وكفرهم؛ ففي هذا أنّ العذابَ دركاتٌ بحسبِ الجرم؛ فاحذر المعاصيَ التي تُدخل أبوابَ جهنم، واعمل بما يرفعك في درجاتِ الجنّة لا يهوي بك في دركاتِ النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من المعاصي التي تُدخل دركاتِ جهنم."},"action":{"text":"احذر المعاصيَ والكفرَ التي تُهوي بصاحبها في دركاتِ جهنمَ وأبوابها، واعمل بالطاعةِ التي ترفعك في درجاتِ الجنّة."}}]},{"title":"نعيمُ المتقين في الجناتِ والعيون","range":[45,48],"theme":"جزاءُ المتقين بالجناتِ والأمنِ والسلامةِ ونزعِ الغلّ","verses":[{"n":45,"reflection":{"text":"«إن المتقين في جنات وعيون» — إنّ الذين اتّقوا الله في الدنيا في جناتٍ ذاتِ بساتينَ وعيونٍ جاريةٍ يوم القيامة؛ ففي هذا أنّ التقوى سبيلُ الجناتِ والعيون؛ فاتّق الله في الدنيا لتنال جناتِ النعيمِ في الآخرة، فجزاءُ المتقين نعيمٌ مقيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّقاءُ الله في الدنيا لنيلِ جناتِ النعيمِ في الآخرة."},"action":{"text":"اتّق الله في سرّك وعلنك، فجزاءُ المتقين جناتٌ وعيونٌ، فاعمل بالتقوى لتنال هذا النعيمَ المقيم."}},{"n":46,"reflection":{"text":"«ادخلوها بسلام آمنين» — يُقال للمتقين: ادخلوا الجناتِ سالمين من كلِّ آفةٍ ومكروه، آمنين من كلِّ خوفٍ وزوالٍ للنعيم؛ ففي هذا أنّ الجنّةَ دارُ سلامٍ وأمن؛ فاعمل لتُستقبَل بـ«ادخلوها بسلامٍ آمنين»، فتلك بشارةُ أهلِ التقوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["بسلام آمنين"],"heart_state":{"text":"العملُ لنيلِ دارِ السلامِ والأمنِ في الجنّة."},"action":{"text":"اعمل بالطاعةِ والتقوى لتدخل الجنّةَ بسلامٍ آمنًا من كلِّ خوفٍ وآفة، فتلك دارُ السلامةِ والأمنِ الدائم."}},{"n":47,"reflection":{"text":"«ونزعنا ما في صدورهم من غل إخوانا على سرر متقابلين» — ونزعنا ما في صدورِ أهلِ الجنّةِ من حقدٍ وحسدٍ وعداوة، فصاروا إخوانًا متحابّين على سررِ الكرامةِ يقابل بعضهم بعضًا بالمودّةِ والمحبّة؛ ففي هذا أنّ من نعيمِ الجنّةِ سلامةَ الصدورِ والأخوّة، وأنّ الغلَّ من مكدّراتِ العيش؛ فطهّر قلبك من الغلِّ والحسدِ في الدنيا، فسلامةُ الصدرِ من صفاتِ أهلِ الجنّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["نزعنا ما في صدورهم من غل"],"heart_state":{"text":"تطهيرُ القلبِ من الغلِّ والحسد، فسلامةُ الصدرِ من صفاتِ أهلِ الجنّة."},"action":{"text":"طهّر قلبك من الغلِّ والحقدِ والحسدِ على إخوانك، وكن سليمَ الصدرِ محبًّا للخير، فسلامةُ الصدرِ من صفاتِ أهلِ الجنّة."}},{"n":48,"reflection":{"text":"«لا يمسهم فيها نصب وما هم منها بمخرجين» — لا يصيب أهلَ الجنّةِ فيها تعبٌ ولا مشقّةٌ ولا نصب، وما هم بمُخرَجين منها أبدًا بل خالدون؛ ففي هذا أنّ نعيمَ الجنّةِ خالٍ من التعبِ دائمٌ لا ينقطع؛ فاعمل لنعيمٍ لا تعبَ فيه ولا زوال، فذاك جزاءُ الصابرين المتقين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمٍ دائمٍ لا تعبَ فيه ولا زوال."},"action":{"text":"اعمل لنعيمِ الجنّةِ الذي لا يمسّ أهلَه تعبٌ ولا يُخرَجون منه، فهو دائمٌ لا يزول، جزاءً لأهلِ الإيمانِ والتقوى."}}]},{"title":"الإخبارُ عن مغفرةِ الله وعذابه","range":[49,50],"theme":"الجمعُ بين رجاءِ مغفرةِ الله وخوفِ عذابه","verses":[{"n":49,"reflection":{"text":"«نبئ عبادي أني أنا الغفور الرحيم» — أخبر يا محمد عبادي أني أنا الغفورُ الواسعُ المغفرةِ لمن تاب، الرحيمُ الواسعُ الرحمةِ بعباده؛ ففي هذا فتحُ بابِ الرجاءِ للعباد، وأنّ الله كثيرُ المغفرةِ والرحمة؛ فارجُ مغفرةَ الله ورحمته، وتب إليه، فهو الغفورُ الرحيمُ لمن أقبل عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"الرجاءُ في مغفرةِ الله ورحمته الواسعة."},"action":{"text":"ارجُ مغفرةَ الله ورحمته، وتب إليه من ذنوبك، فهو الغفورُ الرحيمُ يقبل التوبةَ ويرحم من أقبل عليه."}},{"n":50,"reflection":{"text":"«وأن عذابي هو العذاب الأليم» — وأخبرهم أنّ عذابي هو العذابُ الأليمُ الموجعُ لمن أصرّ على الكفرِ والمعصية؛ ففي هذا موازنةُ الرجاءِ بالخوف، فلا يأمن العبدُ مكرَ الله ولا ييأس من رحمته؛ فاجمع في قلبك بين رجاءِ مغفرةِ الله وخوفِ عذابه، فلا تأمن ولا تيأس، بل سر إليه بين الخوفِ والرجاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العذاب الأليم"],"heart_state":{"text":"الجمعُ بين رجاءِ المغفرةِ وخوفِ العذاب، فلا أمنَ ولا يأس."},"action":{"text":"اجمع في قلبك بين رجاءِ مغفرةِ الله وخوفِ عذابه الأليم، فلا تأمن مكره ولا تيأس من رحمته، بل سر إليه بينهما."}}]},{"title":"ضيفُ إبراهيمَ والبشرى بالغلام","range":[51,53],"theme":"إكرامُ إبراهيمَ لضيوفه، وبشارةُ الملائكةِ له بولدٍ عليم","verses":[{"n":51,"reflection":{"text":"«ونبئهم عن ضيف إبراهيم» — وأخبر يا محمد عبادي عن أضيافِ إبراهيمَ (الملائكةِ الذين جاؤوه في صورةِ بشر)، ليعتبروا بما فيها من العبرِ في رحمةِ الله بأوليائه وعذابه لأعدائه؛ ففي هذا أنّ في قصصِ الأنبياءِ عبرًا؛ فتدبّر قصصَ الأنبياءِ لتأخذ منها العبرَ في رحمةِ الله بالمؤمنين وعدله في المجرمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التدبّرُ في قصصِ الأنبياءِ لأخذِ العبرِ منها."},"action":{"text":"تدبّر قصصَ الأنبياءِ وأضيافهم، لتعتبر برحمةِ الله بأوليائه وعدله في أعدائه، فالقصصُ عبرةٌ لمن تدبّر."}},{"n":52,"reflection":{"text":"«إذ دخلوا عليه فقالوا سلاما قال إنا منكم وجلون» — إذ دخل الملائكةُ على إبراهيمَ فحيّوه بالسلام، فلمّا قدّم لهم الطعامَ ولم يأكلوا قال: إنا منكم خائفون (ظنّهم يريدون سوءًا)؛ ففي هذا حسنُ ضيافةِ إبراهيمَ وردُّه السلام؛ فأكرم ضيوفك وابدأهم بالسلام، ورُدَّ التحيّةَ بأحسنَ منها اقتداءً بالخليل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إكرامُ الضيفِ وردُّ التحيّةِ اقتداءً بإبراهيم."},"action":{"text":"أكرم ضيوفك بحسنِ الاستقبالِ والطعام، وابدأهم بالسلامِ ورُدَّ التحيّة، اقتداءً بإبراهيمَ خليلِ الله في كرمه."}},{"n":53,"reflection":{"text":"«قالوا لا توجل إنا نبشرك بغلام عليم» — قالت الملائكةُ لإبراهيم: لا تخف، إنا نبشّرك بولدٍ عليمٍ (إسحاقَ الذي يكون نبيًّا عالمًا)؛ ففي هذا بشارةُ الله لإبراهيمَ بذرّيّةٍ صالحةٍ عالمة، وأنّ العلمَ شرفٌ يُبشَّر به؛ فاطلب من الله الذرّيّةَ الصالحةَ العالمة، وأبشر بأنّ فضلَ الله واسع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["غلام عليم"],"heart_state":{"text":"طلبُ الذرّيّةِ الصالحةِ العالمة، والبشارةُ بفضلِ الله."},"action":{"text":"اسأل الله ذرّيّةً صالحةً عالمة، وأبشر بفضله الواسع، فقد بشّر إبراهيمَ بغلامٍ عليم، والعلمُ شرفٌ يُبشَّر به."}}]},{"title":"عجبُ إبراهيمَ، والنهيُ عن القنوط","range":[54,56],"theme":"أنّ القنوطَ من رحمةِ الله من صفاتِ الضالّين، وأنّ رحمته لا تحدّها عادة","verses":[{"n":54,"reflection":{"text":"«قال أبشرتموني على أن مسني الكبر فبم تبشرون» — قال إبراهيمُ متعجّبًا: أتبشّرونني بالولدِ وقد بلغني الكِبَرُ والشيخوخة؟ فبأيِّ شيءٍ عجيبٍ تبشّرونني وهذا خلافُ العادة؟ ففي هذا تعجّبُه من خرقِ العادةِ لا شكًّا في قدرةِ الله؛ فاعلم أنّ قدرةَ الله فوق العادات، فما استبعدته العادةُ هيّنٌ على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ قدرةَ الله فوق العاداتِ والأسباب."},"action":{"text":"أيقن أنّ قدرةَ الله لا تحدّها عادةٌ ولا سنّ، فما تراه بعيدًا في العادةِ هيّنٌ على الله إذا أراده، فلا تستبعد فضله."}},{"n":55,"reflection":{"text":"«قالوا بشرناك بالحق فلا تكن من القانطين» — قالت الملائكةُ: بشّرناك بالحقِّ الثابتِ الذي لا شكَّ فيه، فلا تكن من الآيسين القانطين من رحمةِ الله وفضله؛ ففي هذا أنّ بشارةَ الله حقٌّ، وأنّ القنوطَ منهيٌّ عنه؛ فلا تقنط من رحمةِ الله وفضله مهما تأخّرت الأسباب، فبشارتُه حقٌّ نافذ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"النهيُ عن القنوطِ من رحمةِ الله وفضله."},"action":{"text":"لا تقنط من رحمةِ الله وفضله مهما ضاقت الأسباب أو تأخّرت، فوعدُه حقٌّ نافذ، والقنوطُ منهيٌّ عنه."}},{"n":56,"reflection":{"text":"«قال ومن يقنط من رحمة ربه إلا الضالون» — قال إبراهيم: ومن ييأس من رحمةِ ربّه إلا الضالّون عن معرفةِ الله وسَعةِ رحمته؟ ففي هذا أنّ القنوطَ من رحمةِ الله ضلالٌ وجهلٌ بالله، وأنّ المؤمنَ لا ييأس من رحمته؛ فأحسن ظنّك بالله ولا تيأس من رحمته، فاليأسُ منها ضلالٌ وجهلٌ بسَعةِ فضله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["رحمة ربه"],"heart_state":{"text":"حسنُ الظنِّ بالله وعدمُ اليأسِ من رحمته، فاليأسُ ضلال."},"action":{"text":"أحسن ظنّك بالله ولا تيأس من رحمته مهما عظمت ذنوبك أو ضاقت أحوالك، فالقنوطُ من رحمةِ الله ضلالٌ وجهلٌ بسَعتها."}}]},{"title":"مهمّةُ الملائكةِ إلى قومِ لوط","range":[57,60],"theme":"إرسالُ الملائكةِ لإهلاكِ المجرمين ونجاةِ آلِ لوطٍ إلا امرأته","verses":[{"n":57,"reflection":{"text":"«قال فما خطبكم أيها المرسلون» — قال إبراهيم للملائكة: فما شأنكم العظيمُ الذي جئتم من أجله أيها المرسلون؟ ففي هذا حرصُ إبراهيمَ على معرفةِ الأمرِ لعلّه يشفع؛ ففي هذا أنّ المؤمنَ يهتمّ بأمورِ إخوانه ويسأل عنهم؛ فاهتمّ بأحوالِ الناسِ واسأل عنهم رحمةً وشفقةً بهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاهتمامُ بأحوالِ الناسِ والسؤالُ عنهم رحمةً بهم."},"action":{"text":"اهتمّ بأحوالِ إخوانك والناسِ من حولك واسأل عنهم بشفقةٍ ورحمة، كما سأل إبراهيمُ الملائكةَ رجاءَ الخيرِ للناس."}},{"n":58,"reflection":{"text":"«قالوا إنا أرسلنا إلى قوم مجرمين» — قالت الملائكة: إنا أُرسلنا إلى قومٍ مجرمين (قومِ لوطٍ) لإهلاكهم بجرمهم؛ ففي هذا أنّ الإجرامَ والإصرارَ عليه سببُ الهلاك؛ فاحذر الإجرامَ والفواحشَ فعاقبتها الاستئصال، ولا تكن من القومِ المجرمين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإجرامِ والفواحشِ فعاقبتها الهلاك."},"action":{"text":"احذر الإجرامَ والفواحشَ والإصرارَ عليها، فعاقبةُ القومِ المجرمين الاستئصالُ والهلاك، والزم الطاعةَ والطهر."}},{"n":59,"reflection":{"text":"«إلا آل لوط إنا لمنجوهم أجمعين» — إلا آلَ لوطٍ (أتباعه المؤمنين وأهلَ بيته) فإنا منجّوهم أجمعين من العذابِ الذي يحلّ بالمجرمين؛ ففي هذا أنّ الله ينجّي المؤمنين من عذابِ الظالمين؛ فالزم الإيمانَ والطاعةَ لتكون من الناجين، فالله يميّز المؤمنَ من المجرمِ في النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الله ينجّي المؤمنين من عذابِ المجرمين."},"action":{"text":"الزم الإيمانَ والطاعة، وأبشر بأنّ الله ينجّي المؤمنين من عذابِ الظالمين كما نجّى آلَ لوط، فالعبرةُ بالإيمان."}},{"n":60,"reflection":{"text":"«إلا امرأته قدرنا إنها لمن الغابرين» — إلا امرأةَ لوطٍ (الكافرةَ) قدّرنا أنها ممّن يبقى في العذابِ مع الهالكين، لأنها كانت على دينِ قومها؛ ففي هذا أنّ النجاةَ بالإيمانِ لا بالقرابة، وأنّ زوجةَ النبيِّ لم تنفعها القرابةُ مع الكفر؛ فاعلم أنّ النجاةَ بالعملِ والإيمانِ لا بالنسبِ ولا الصحبة، فاحرص على إيمانك وعملك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ النجاةَ بالإيمانِ والعملِ لا بالقرابةِ ولا الصحبة."},"action":{"text":"اطلب نجاتك بإيمانك وعملك لا بقرابةٍ أو صحبةِ صالحين، فامرأةُ لوطٍ هلكت بكفرها رغم قربها من نبيّ الله."}}]},{"title":"مجيءُ الملائكةِ إلى لوط، وأمرُ الإسراءِ بأهله","range":[61,66],"theme":"طمأنةُ الملائكةِ للوط، وأمرُه بالخروجِ بأهله، واستئصالُ المجرمين","verses":[{"n":61,"reflection":{"text":"«فلما جاء آل لوط المرسلون» — فلما جاء الملائكةُ المرسلون آلَ لوطٍ في صورةِ شبابٍ حِسان؛ ففي هذا ابتداءُ الفرجِ بعد الكرب، وأنّ الله يرسل رسله لنصرةِ أوليائه؛ فاطمئن إلى أنّ الله يرسل عونه لأوليائه عند اشتدادِ الكرب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى أنّ الله يرسل عونه لأوليائه عند الكرب."},"action":{"text":"اطمئن إلى أنّ الله لا يترك أولياءه في كربهم، بل يرسل عونه ونصره عند اشتدادِ الشدّة، كما أرسل الملائكةَ للوط."}},{"n":62,"reflection":{"text":"«قال إنكم قوم منكرون» — قال لوطٌ للملائكة (ولم يعرفهم): إنكم قومٌ غرباءُ لا أعرفكم، فخاف عليهم من قومه؛ ففي هذا غيرةُ لوطٍ وخوفُه على ضيوفه من فسادِ قومه؛ ففي هذا أنّ الغيرةَ على الحرماتِ من الإيمان؛ فكن غيورًا على محارمِ الله والأعراضِ، حذرًا من مواطنِ الفساد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الغيرةُ على الحرماتِ والأعراضِ، والحذرُ من مواطنِ الفساد."},"action":{"text":"كن غيورًا على محارمِ الله والأعراض، حذرًا من مواطنِ الفساد، كما خاف لوطٌ على ضيوفه من فسادِ قومه."}},{"n":63,"reflection":{"text":"«قالوا بل جئناك بما كانوا فيه يمترون» — قالت الملائكةُ للوط: لا تخف، بل جئناك بالعذابِ الذي كان قومك يشكّون فيه ويكذّبون به؛ ففي هذا أنّ ما استبعده المكذّبون واقعٌ بهم؛ ففي هذا أنّ وعيدَ الله واقعٌ ولو استبعده المكذّبون؛ فلا تستبعد وعيدَ الله، فما شكّ فيه المجرمون نازلٌ بهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ وعيدَ الله واقعٌ ولو استبعده المكذّبون."},"action":{"text":"لا تستبعد وعيدَ الله وعقوبته، فما شكّ فيه المكذّبون واستبعدوه نازلٌ بهم لا محالة، فخذ حذرك واستعدّ."}},{"n":64,"reflection":{"text":"«وأتيناك بالحق وإنا لصادقون» — وأتيناك بالأمرِ الحقِّ الثابت (العذابِ الواقع)، وإنا لصادقون فيما أخبرناك به لا كذبَ فيه؛ ففي هذا تأكيدُ الملائكةِ صدقَ خبرهم؛ ففي هذا أنّ أخبارَ الوحيِ حقٌّ وصدق؛ فأيقن بصدقِ ما جاء عن الله، فأخبارُه كلُّها حقٌّ لا ريبَ فيها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بصدقِ ما جاء عن الله من الأخبار."},"action":{"text":"أيقن بصدقِ كلِّ ما جاء عن الله في وحيه، فأخبارُه حقٌّ لا كذبَ فيها، واعمل بمقتضى هذا اليقين."}},{"n":65,"reflection":{"text":"«فأسر بأهلك بقطع من الليل واتبع أدبارهم ولا يلتفت منكم أحد وامضوا حيث تؤمرون» — فسر يا لوطُ بأهلك في جزءٍ من آخرِ الليل، وكن خلفهم تحرسهم وتحثّهم، ولا يلتفت منكم أحدٌ إلى ما وراءه (لئلا يرى العذابَ أو تشغله الدنيا)، وامضوا إلى حيث يأمركم الله؛ ففي هذا حرصُ الله على نجاةِ لوطٍ وأهله بأمرهم بالحيطة؛ ففي هذا أنّ النجاةَ بامتثالِ أمرِ الله والمضيِّ حيث يأمر؛ فامضِ حيث يأمرك الله ولا تلتفت إلى ما تركت، فالنجاةُ في طاعته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"النجاةُ بامتثالِ أمرِ الله والمضيِّ حيث يأمر بلا التفات."},"action":{"text":"امتثل أمرَ الله وامضِ حيث يأمرك، ولا تلتفت إلى ما تركت من دنيا أو مألوف، فالنجاةُ في طاعته والمضيِّ على أمره."}},{"n":66,"reflection":{"text":"«وقضينا إليه ذلك الأمر أن دابر هؤلاء مقطوع مصبحين» — وأوحينا إلى لوطٍ ذلك الأمرَ المقضيَّ: أنّ آخرَ هؤلاءِ القومِ مستأصَلٌ مقطوعٌ عن آخرهم وقتَ الصباح، فلا يبقى منهم أحد؛ ففي هذا أنّ عذابَ الله إذا نزل استأصل الظالمين؛ فاحذر أسبابَ عذابِ الله، فعقوبته للظالمين استئصالٌ لا يبقي منهم أحدًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أسبابِ عذابِ الله الذي يستأصل الظالمين."},"action":{"text":"احذر أسبابَ عذابِ الله من الظلمِ والفواحش، فعقوبته للظالمين استئصالٌ يقطع دابرهم، والزم الطاعةَ لتنجو."}}]},{"title":"مجيءُ أهلِ المدينةِ للفاحشة","range":[67,67],"theme":"مجاهرةُ قومِ لوطٍ بالفاحشةِ حتى استبشروا بالضيوف","verses":[{"n":67,"reflection":{"text":"«وجاء أهل المدينة يستبشرون» — وجاء أهلُ مدينةِ لوطٍ (سدوم) مسرعين فرحين مستبشرين حين علموا بالضيوفِ الحِسان، طمعًا في فعلِ الفاحشةِ بهم؛ ففي هذا أنّ قومَ لوطٍ بلغوا في الفاحشةِ حدَّ المجاهرةِ والفرحِ بها؛ ففي هذا أنّ المجاهرةَ بالمعصيةِ والفرحَ بها من أعظمِ الجرأةِ على الله؛ فاحذر المجاهرةَ بالمعاصي والفرحَ بها، فذاك منتهى الانتكاسِ والجرأة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من المجاهرةِ بالمعاصي والفرحِ بها."},"action":{"text":"احذر المجاهرةَ بالمعاصي والفرحَ بها، فذاك منتهى الجرأةِ على الله وانتكاسِ الفطرة، والزم الحياءَ والستر."}}]},{"title":"استنجادُ لوطٍ بضيوفه، ومكابرةُ قومه","range":[68,71],"theme":"مناشدةُ لوطٍ قومه بالتقوى، وإصرارُهم على الفاحشة","verses":[{"n":68,"reflection":{"text":"«قال إن هؤلاء ضيفي فلا تفضحون» — قال لوطٌ لقومه مستنجدًا: إنّ هؤلاءِ ضيفي نزلوا بي، فلا تفضحوني فيهم بالتعرّضِ لهم بالسوء؛ ففي هذا حرمةُ الضيفِ وحقُّه على مضيفه في الحمايةِ والصيانة؛ فاحفظ حرمةَ ضيفك وصُنه، فحمايةُ الضيفِ من كرمِ الأخلاق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ حرمةِ الضيفِ وصيانتُه من كرمِ الأخلاق."},"action":{"text":"احفظ حرمةَ ضيفك وصُنه من كلِّ أذًى، فحمايةُ الجارِ والضيفِ وصيانتُهما من مكارمِ الأخلاقِ التي أمر بها الإسلام."}},{"n":69,"reflection":{"text":"«واتقوا الله ولا تخزون» — وقال لوط: واتّقوا الله في أنفسكم وفي ضيفي، ولا تخزوني وتذلّوني بفعلِ الفاحشةِ بمن نزل بي؛ ففي هذا أنّ التذكيرَ بتقوى الله سلاحُ الداعيةِ في ردعِ المنكر؛ فذكّر الناسَ بتقوى الله عند إنكارِ المنكر، فهي أعظمُ رادع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكيرُ بتقوى الله عند إنكارِ المنكرِ رادعًا."},"action":{"text":"ذكّر الناسَ بتقوى الله عند إنكارِ المنكر، فالتخويفُ بالله أعظمُ رادعٍ، واتّق الله في حقوقِ من استُرعيت أمانتهم."}},{"n":70,"reflection":{"text":"«قالوا أولم ننهك عن العالمين» — قال قومُ لوطٍ مكابرين: أولم ننهك أن تُضيّف أحدًا من الناسِ أو تدافع عنهم؟ فردّوا نصحه بالتهديد؛ ففي هذا أنّ أهلَ الباطلِ يقابلون النصحَ بالمكابرةِ والتهديد؛ فلا يصدّك تهديدُ أهلِ الباطلِ عن إنكارِ المنكرِ والقيامِ بالحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على إنكارِ المنكرِ رغمَ مكابرةِ أهلِ الباطلِ وتهديدهم."},"action":{"text":"لا يصدّك تهديدُ أهلِ الباطلِ ومكابرتُهم عن إنكارِ المنكرِ والقيامِ بالحقّ، فاثبت كما ثبت لوطٌ في وجهِ قومه."}},{"n":71,"reflection":{"text":"«قال هؤلاء بناتي إن كنتم فاعلين» — قال لوطٌ عارضًا الحلالَ بديلًا: هؤلاءِ بناتي (نساءُ أمّتي، أو بناتُه) فتزوّجوهنّ إن كنتم لا بدّ فاعلين قضاءَ الشهوة؛ ففي هذا دفعُ لوطٍ الفاحشةَ بالحلالِ البديل؛ فادفع المنكرَ ما استطعت، ودُلَّ على الحلالِ بديلًا عن الحرام، فذاك من حكمةِ الدعوة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"دفعُ المنكرِ بالبديلِ الحلال، ودلالةُ الناسِ عليه."},"action":{"text":"ادفع المنكرَ ما استطعت، ودُلَّ الناسَ على الحلالِ بديلًا عن الحرام، فذاك من حكمةِ الدعوةِ ورحمتها بالخلق."}}]},{"title":"عذابُ قومِ لوطٍ بالصيحةِ والحجارة","range":[72,74],"theme":"غفلةُ القومِ في سكرتهم، ونزولُ العذابِ باستئصالهم","verses":[{"n":72,"reflection":{"text":"«لعمرك إنهم لفي سكرتهم يعمهون» — أقسم الله بحياةِ نبيّه محمدٍ ﷺ (وهو أشرفُ قسم): إنّ قومَ لوطٍ لفي غفلةِ ضلالهم وسكرةِ شهوتهم يتردّدون حائرين لا يبصرون رشدًا؛ ففي هذا أنّ الشهوةَ تُسكِر القلبَ عن الحقِّ كسكرِ الخمر، وأنّ لمحمدٍ ﷺ عند الله منزلةً عظيمةً أقسم بحياته؛ فاحذر سكرةَ الشهوةِ التي تُعمي عن الحقّ، وعظّم قدرَ نبيّك الذي أقسم الله بحياته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من سكرةِ الشهوةِ التي تُعمي عن الحقّ، وتعظيمُ النبيِّ ﷺ."},"action":{"text":"احذر أن تُسكرك الشهوةُ عن رؤيةِ الحقِّ كما أسكرت قومَ لوط، وعظّم قدرَ نبيّك ﷺ الذي أقسم الله بحياته إجلالًا له."}},{"n":73,"reflection":{"text":"«فأخذتهم الصيحة مشرقين» — فأخذت قومَ لوطٍ الصيحةُ المهلكةُ وقتَ شروقِ الشمس؛ ففي هذا سرعةُ أخذِ الله للمجرمين بأمرٍ يسير؛ فاحذر أن يأخذك الله بغتةً في غفلتك، فأخذُه للمجرمين سريعٌ لا يُدفع، فبادر بالتوبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أخذِ الله البغتةِ للمجرمين في غفلتهم."},"action":{"text":"احذر أن يأخذك الله بغتةً وأنت غافلٌ في معصيتك، فأخذُه للمجرمين سريعٌ لا يُدفع، فبادر بالتوبةِ قبل الفوات."}},{"n":74,"reflection":{"text":"«فجعلنا عاليها سافلها وأمطرنا عليهم حجارة من سجيل» — فقلبنا قريتهم فجعلنا أعلاها أسفلها، وأمطرنا عليهم حجارةً من طينٍ متحجّرٍ (سِجّيل)؛ ففي هذا شدّةُ عقوبةِ الله لأهلِ الفاحشةِ المصرّين؛ فاحذر الفواحشَ والإصرارَ عليها، فعقوبةُ الله لأهلها قلبُ الديارِ وإمطارُ الحجارة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الفواحشِ فعقوبةُ الله لأهلها الاستئصال."},"action":{"text":"احذر الفواحشَ والإصرارَ عليها، فعقوبةُ الله لأهلها شديدة: قلبُ الديارِ وإمطارُ الحجارة، والزم الطهرَ والعفّة."}}]},{"title":"آياتٌ للمتوسّمين والمؤمنين","range":[75,77],"theme":"أنّ في آثارِ الهالكين عبرًا لأهلِ الفراسةِ والإيمان","verses":[{"n":75,"reflection":{"text":"«إن في ذلك لآيات للمتوسمين» — إنّ في إهلاكِ قومِ لوطٍ وآثارهم لعبرًا ودلائلَ للمتوسّمين (المتفرّسين المتأمّلين الذين يعتبرون بالعلامات)؛ ففي هذا أنّ العبرةَ لأهلِ التأمّلِ والفراسة؛ فتأمّل آياتِ الله وآثارَ عقوباته بفراسةِ المؤمن، لتأخذ منها العبرةَ والعظة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ بفراسةِ المؤمنِ في آياتِ الله وآثارِ عقوباته."},"action":{"text":"تأمّل آثارَ الأممِ الهالكةِ وآياتِ الله بفراسةِ المؤمنِ المتوسّم، لتأخذ منها العبرةَ والعظة، فالعبرةُ لأهلِ التأمّل."}},{"n":76,"reflection":{"text":"«وإنها لبسبيل مقيم» — وإنّ قرى قومِ لوطٍ لبطريقٍ ثابتٍ يمرّ به المسافرون (بين الحجازِ والشام) فيرون آثارها فيعتبرون؛ ففي هذا أنّ آثارَ العبرةِ قائمةٌ ظاهرةٌ لمن مرّ بها؛ فاعتبر بآثارِ العقوباتِ القائمةِ في طريقك، فالله يبقيها عبرةً للمعتبرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بآثارِ العقوباتِ القائمةِ الظاهرةِ للناس."},"action":{"text":"اعتبر بآثارِ الأممِ الهالكةِ القائمةِ في طرقاتك وأخبارها، فالله أبقاها عبرةً ظاهرةً لمن مرّ بها واتّعظ."}},{"n":77,"reflection":{"text":"«إن في ذلك لآية للمؤمنين» — إنّ في ذلك الإهلاكِ لعبرةً ودلالةً للمؤمنين خاصّةً، فهم المنتفعون بالآياتِ لصدقِ إيمانهم؛ ففي هذا أنّ الانتفاعَ بالآياتِ خاصٌّ بالمؤمنين؛ فاجعل إيمانك يفتح قلبك للاعتبارِ بآياتِ الله، فالمؤمنُ هو المنتفعُ بالعبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الانتفاعَ بآياتِ الله خاصٌّ بأهلِ الإيمان."},"action":{"text":"قوِّ إيمانك ليفتح قلبك للاعتبارِ بآياتِ الله وآثارِ عقوباته، فالمؤمنُ هو المنتفعُ بالعبرِ دون الغافلِ المعرض."}}]},{"title":"عقوبةُ أصحابِ الأيكة","range":[78,79],"theme":"إهلاكُ قومِ شعيبٍ لظلمهم، وأنّ آثارهم بطريقٍ ظاهر","verses":[{"n":78,"reflection":{"text":"«وإن كان أصحاب الأيكة لظالمين» — وقد كان أصحابُ الأيكةِ (قومُ شعيبٍ، وكانوا أصحابَ شجرٍ ملتفّ) ظالمين بالكفرِ والتطفيفِ في الكيلِ والميزان؛ ففي هذا أنّ الظلمَ بأنواعه سببُ العقوبة؛ فاحذر الظلمَ في الحقوقِ والمعاملات، فهو سببُ الهلاكِ كما أهلك أصحابَ الأيكة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ في الحقوقِ والمعاملاتِ فهو سببُ الهلاك."},"action":{"text":"احذر الظلمَ بكلِّ أنواعه في الحقوقِ والبيعِ والمعاملات، فالظلمُ سببُ الهلاك، كما أهلك الله أصحابَ الأيكةِ بظلمهم."}},{"n":79,"reflection":{"text":"«فانتقمنا منهم وإنهما لبإمام مبين» — فانتقمنا من أصحابِ الأيكةِ بالعذاب، وإنّ قرى قومِ لوطٍ والأيكةِ لبطريقٍ واضحٍ ظاهرٍ يراه المارّون فيعتبرون؛ ففي هذا أنّ الله ينتقم من الظالمين، وأنّ آثارهم عبرةٌ قائمة؛ فاعتبر بانتقامِ الله من الظالمين، ولا تسلك سبيلهم فينالك انتقامه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بانتقامِ الله من الظالمين، وتجنّبُ سبيلهم."},"action":{"text":"اعتبر بانتقامِ الله من الظالمين وآثارهم القائمة، ولا تسلك سبيلهم في الظلمِ والكفر، فينالك ما نالهم من العقاب."}}]},{"title":"تكذيبُ أصحابِ الحِجرِ وعاقبتُهم","range":[80,84],"theme":"إعراضُ ثمودَ عن آياتِ الله رغمَ قوّتهم، وأنّ كسبهم لم يُغنِ عنهم","verses":[{"n":80,"reflection":{"text":"«ولقد كذب أصحاب الحجر المرسلين» — ولقد كذّب أصحابُ الحِجرِ (ثمودُ، قومُ صالحٍ، وكانوا يسكنون الحِجرَ بين الحجازِ والشام) رسلهم (وتكذيبُ رسولٍ تكذيبٌ لكلِّ الرسل)؛ ففي هذا أنّ التكذيبَ سببُ الهلاك؛ فاحذر تكذيبَ الحقِّ وأهله، فتكذيبُ رسولٍ تكذيبٌ للجميعِ وسببُ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تكذيبِ الحقِّ ورسله، فهو سببُ الهلاك."},"action":{"text":"احذر تكذيبَ الحقِّ ورسله، فتكذيبُ رسولٍ تكذيبٌ للجميع، والزم تصديقَ ما جاء عن الله واتّباعه."}},{"n":81,"reflection":{"text":"«وآتيناهم آياتنا فكانوا عنها معرضين» — وأعطينا ثمودَ آياتنا الدالّةَ على صدقِ صالح (كالناقة)، فكانوا عنها معرضين لا يتفكّرون ولا يعتبرون؛ ففي هذا أنّ الإعراضَ عن الآياتِ سببُ الحرمان؛ فلا تعرض عن آياتِ الله، بل تأمّلها واعتبر بها، فالإعراضُ عنها كفرانٌ لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإعراضِ عن آياتِ الله، وتأمّلُها والاعتبارُ بها."},"action":{"text":"لا تعرض عن آياتِ الله الكونيّةِ والشرعيّة، بل تأمّلها واعتبر بها، فالإعراضُ عنها سببُ الحرمانِ والعقوبة."}},{"n":82,"reflection":{"text":"«وكانوا ينحتون من الجبال بيوتا آمنين» — وكانت ثمودُ ينحتون من الجبالِ بيوتًا يسكنونها آمنين مطمئنّين إلى قوّتهم وحصانةِ مساكنهم؛ ففي هذا أنّ القوّةَ والتمكّنَ لا يمنعان عذابَ الله؛ فلا تغترّ بقوّةٍ أو حصنٍ، فلا يعصم من الله شيءٌ إلا طاعتُه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يُغترَّ بالقوّةِ والحصانةِ عن عذابِ الله."},"action":{"text":"لا تغترّ بقوّتك أو مالك أو مسكنك، فلا يعصم من عذابِ الله شيءٌ إلا طاعتُه، فقد نحتت ثمودُ الجبالَ فما أغنت عنهم."}},{"n":83,"reflection":{"text":"«فأخذتهم الصيحة مصبحين» — فأخذت ثمودَ الصيحةُ المهلكةُ وقتَ الصباح، فأصبحوا هامدين؛ ففي هذا سرعةُ أخذِ الله للمكذّبين رغمَ قوّتهم؛ فاحذر أن يأخذك الله بغتةً، فقوّتك وحصنك لا يردّان قضاءه، والنجاةُ بالإيمانِ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أخذِ الله البغتة، فالقوّةُ لا تردّ قضاءه."},"action":{"text":"احذر أن يأخذك الله بغتةً في غفلتك، فقوّتك وحصونك لا تردّ قضاءه، والنجاةُ بالإيمانِ والطاعةِ لا بالقوّة."}},{"n":84,"reflection":{"text":"«فما أغنى عنهم ما كانوا يكسبون» — فما دفع عنهم عذابَ الله ما كانوا يكسبونه من الأموالِ والحصونِ والقوّة، ولا نفعهم شيءٌ من ذلك؛ ففي هذا أنّ ما يجمعه الإنسانُ من قوّةٍ ومالٍ لا يغني عنه من الله شيئًا إذا نزل العذاب؛ فلا تتّكل على مالٍ أو قوّة، فالعاصمُ من عذابِ الله طاعتُه وحدها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يُتّكلَ على مالٍ أو قوّة، فالعاصمُ طاعةُ الله."},"action":{"text":"لا تتّكل على مالٍ أو قوّةٍ أو جاه، فكلُّ ذلك لا يُغني عنك من الله شيئًا، والعاصمُ من عذابه طاعتُه والإيمانُ به وحده."}}]},{"title":"خلقُ الكونِ بالحق، والصفحُ الجميل","range":[85,86],"theme":"أنّ الخلقَ بالحقِّ والساعةَ آتية، فليكن الصفحُ جميلًا","verses":[{"n":85,"reflection":{"text":"«وما خلقنا السماوات والأرض وما بينهما إلا بالحق وإن الساعة لآتية فاصفح الصفح الجميل» — وما خلقنا السماواتِ والأرضَ وما بينهما إلا بالحقِّ والحكمةِ لا عبثًا، وإنّ الساعةَ لآتيةٌ يُجازى فيها كلٌّ بعمله، فاصفح يا محمد عن المسيئين صفحًا جميلًا لا عتابَ معه ولا جزع؛ ففي هذا أنّ اليقينَ بالساعةِ والجزاءِ يهوّن الأذى ويحمل على العفوِ الجميل؛ فاصفح عمّن أساء إليك صفحًا جميلًا، مستحضرًا أنّ الجزاءَ عند الله يوم القيامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الصفح الجميل"],"heart_state":{"text":"الصفحُ الجميلُ عن المسيئين مع اليقينِ بالجزاءِ يوم الساعة."},"action":{"text":"اصفح عمّن أساء إليك صفحًا جميلًا بلا عتابٍ ولا حقد، مستحضرًا أنّ الساعةَ آتيةٌ والجزاءُ عند الله، فذاك أهون للأذى."}},{"n":86,"reflection":{"text":"«إن ربك هو الخلاق العليم» — إنّ ربّك هو الخلّاقُ الكثيرُ الخلقِ لما يشاء، العليمُ بكلِّ ما خلق وبأحوالِ عباده؛ ففي هذا أنّ الخالقَ العليمَ يدبّر أمرك ويعلم حالك، فسلّم له أمرك؛ فاطمئن إلى أنّ ربّك الخلّاقَ العليمَ يدبّر لك الخيرَ ويعلم حالك، فاعتمد عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الخلاق","العليم"],"heart_state":{"text":"الاطمئنانُ إلى تدبيرِ الخلّاقِ العليمِ لأحوالِ عباده."},"action":{"text":"اطمئن إلى أنّ ربّك الخلّاقَ العليمَ يعلم حالك ويدبّر أمرك بحكمة، فسلّم له أمورك واعتمد عليه في كلِّ شأنك."}}]},{"title":"نعمةُ الفاتحةِ والقرآنِ العظيم","range":[87,87],"theme":"امتنانُ الله على نبيّه بالسبعِ المثاني (الفاتحة) والقرآنِ العظيم","verses":[{"n":87,"reflection":{"text":"«ولقد آتيناك سبعا من المثاني والقرآن العظيم» — ولقد أعطيناك يا محمد سورةَ الفاتحةِ (سبعَ آياتٍ تُثنّى وتُكرّر في كلِّ صلاة، كما فسّرها النبيُّ ﷺ)، وأعطيناك القرآنَ العظيمَ كلَّه؛ ففي هذا امتنانُ الله بأعظمِ نعمةٍ: القرآنِ والفاتحة، وأنها خيرٌ من كلِّ متاعِ الدنيا؛ فاعرف قدرَ نعمةِ القرآنِ والفاتحة، فهي خيرٌ ممّا يجمع الناسُ من الدنيا، فاشكرها بالتلاوةِ والعملِ والتدبّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سبعا من المثاني","القرآن العظيم"],"heart_state":{"text":"معرفةُ قدرِ نعمةِ القرآنِ والفاتحة، وشكرُها بالتدبّرِ والعمل."},"action":{"text":"اعرف قدرَ نعمةِ القرآنِ والفاتحةِ التي تكرّرها في صلاتك، فهي خيرٌ من الدنيا وما فيها، فاشكرها بالتلاوةِ والتدبّرِ والعمل."}}]},{"title":"القناعةُ ولينُ الجانبِ للمؤمنين","range":[88,89],"theme":"عدمُ الاغترارِ بمتاعِ الكفار، والتواضعُ للمؤمنين","verses":[{"n":88,"reflection":{"text":"«لا تمدن عينيك إلى ما متعنا به أزواجا منهم ولا تحزن عليهم واخفض جناحك للمؤمنين» — لا تنظر يا محمد بعينِ التمنّي إلى ما متّعنا به أصنافًا من الكفارِ من زهرةِ الدنيا، فما عندك خيرٌ منه، ولا تحزن على إعراضهم، وألِن جانبك وتواضع للمؤمنين؛ ففي هذا أنّ القناعةَ بما عند الله خيرٌ من متاعِ الدنيا، وأنّ التواضعَ للمؤمنين من الأخلاق؛ فلا تمدّ عينك إلى متاعِ الدنيا عند غيرك، واخفض جناحك وتواضع لإخوانك المؤمنين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["واخفض جناحك للمؤمنين"],"heart_state":{"text":"القناعةُ وعدمُ التطلّعِ لمتاعِ الغير، والتواضعُ للمؤمنين."},"action":{"text":"لا تمدّ عينك متمنّيًا ما عند الناسِ من متاعِ الدنيا، فما عند الله خيرٌ وأبقى، وتواضع لإخوانك المؤمنين وألِن لهم جانبك."}},{"n":89,"reflection":{"text":"«وقل إني أنا النذير المبين» — وقل يا محمد للناس: إني أنا النذيرُ البيّنُ الإنذارِ من عذابِ الله لمن كفر؛ ففي هذا أنّ وظيفةَ النبيِّ الإنذارُ والبيان؛ فأنذر من حولك من عاقبةِ الكفرِ والمعصيةِ بوضوحٍ وبيان، اقتداءً بالنبيِّ النذيرِ المبين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنذارُ والبيانُ للناسِ عن عاقبةِ الكفرِ والمعصية."},"action":{"text":"أنذر من حولك بوضوحٍ عن عاقبةِ الكفرِ والمعصية، وبلّغ الحقَّ بيّنًا، اقتداءً بالنبيِّ الذي أُمر أن يقول «إني أنا النذير المبين»."}}]},{"title":"وعيدُ المقتسمين المفرّقين للقرآن","range":[90,93],"theme":"وعيدُ من فرّق القرآنَ وآمن ببعضه، ومساءلتُهم عن أعمالهم","verses":[{"n":90,"reflection":{"text":"«كما أنزلنا على المقتسمين» — أنذرتك يا محمد عذابًا كما أنزلنا العذابَ على المقتسمين (الذين اقتسموا كتابَ الله فآمنوا ببعضه وكفروا ببعض، أو اقتسموا طرقَ مكّةَ يصدّون عن النبيِّ)؛ ففي هذا أنّ تفريقَ الدينِ والصدَّ عنه سببُ العذاب؛ فلا تفرّق بين آياتِ الله فتؤمن ببعضٍ وتكفر ببعض، بل آمن بالكتابِ كلِّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالكتابِ كلِّه، وعدمُ تفريقِ الدين."},"action":{"text":"آمن بالقرآنِ كلِّه ولا تفرّق بين آياته فتقبل ما يوافق هواك وتردّ غيره، فتفريقُ الدينِ والتحكّمُ فيه بابُ عذاب."}},{"n":91,"reflection":{"text":"«الذين جعلوا القرآن عضين» — الذين جعلوا القرآنَ أجزاءً وأعضاءً متفرّقة، فقالوا: بعضُه سحرٌ وبعضُه شعرٌ وبعضُه أساطير، أو آمنوا ببعضه وكفروا ببعض؛ ففي هذا ذمُّ من يجزّئ القرآنَ ويصفه بالباطل؛ فلا تجزّئ القرآنَ ولا تصفه بغيرِ الحقّ، بل عظّمه وآمن به كلِّه وحدةً واحدة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ كلِّه، وعدمُ تجزئتِه أو وصفِه بالباطل."},"action":{"text":"عظّم القرآنَ ولا تجزّئه أو تصفه بالباطل كالسحرِ والشعر، بل آمن به كلِّه وحدةً واحدةً من عند الله."}},{"n":92,"reflection":{"text":"«فوربك لنسألنهم أجمعين» — فوربّك يا محمد لنسألنّ هؤلاء المقتسمين وجميعَ الخلقِ يوم القيامة؛ ففي هذا أنّ الله يسأل الخلقَ كلَّهم عن أعمالهم، فلا يفلت أحد؛ فاستعدّ لسؤالِ الله عن عملك، فكلٌّ مسؤولٌ لا محالة، فأعدّ للسؤالِ جوابًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ لسؤالِ الله عن العمل، فكلٌّ مسؤول."},"action":{"text":"استعدّ ليومٍ يسألك الله فيه عن عملك، فكلُّ الخلقِ مسؤولون لا يفلت أحد، فأعدّ للسؤالِ جوابًا بالعملِ الصالح."}},{"n":93,"reflection":{"text":"«عما كانوا يعملون» — لنسألنّهم عن كلِّ ما كانوا يعملونه من خيرٍ وشرٍّ فنجازيهم عليه؛ ففي هذا أنّ السؤالَ شاملٌ لكلِّ عمل؛ فراقب الله في كلِّ عملك، فستُسأل عن كلِّ صغيرةٍ وكبيرة، فاجعل عملك كلَّه لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في كلِّ عمل، فالسؤالُ شاملٌ لكلِّ شيء."},"action":{"text":"راقب الله في كلِّ عملٍ صغيرٍ أو كبير، فستُسأل عن كلِّ ما عملت، فاجعل أعمالك كلَّها خالصةً لله موافقةً لشرعه."}}]},{"title":"الأمرُ بالصدعِ بالحق، وكفايةُ الله للمستهزئين","range":[94,96],"theme":"الجهرُ بالدعوةِ والإعراضُ عن المشركين، وكفايةُ الله شرَّ المستهزئين","verses":[{"n":94,"reflection":{"text":"«فاصدع بما تؤمر وأعرض عن المشركين» — فاجهر يا محمد بما أُمرت به من الدعوةِ والتبليغِ جهرًا بيّنًا لا تكتمه، وأعرض عن المشركين ولا تبالِ بأذاهم؛ ففي هذا الأمرُ بالمجاهرةِ بالحقِّ والإعراضِ عن المعاندين؛ فاجهر بالحقِّ الذي تعلمه بلا مواراة، وأعرض عن أذى المعاندين ولا يصدّك عن دعوتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["فاصدع بما تؤمر"],"heart_state":{"text":"المجاهرةُ بالحقِّ، والإعراضُ عن أذى المعاندين."},"action":{"text":"اجهر بالحقِّ الذي أمرك الله به بلا كتمانٍ ولا مواراة، وأعرض عن أذى المعاندين ولا تبالِ بهم، فذاك أمرُ الله لنبيّه."}},{"n":95,"reflection":{"text":"«إنا كفيناك المستهزئين» — إنا كفيناك يا محمد شرَّ المستهزئين بك من كبراءِ قريش، فأهلكناهم أو دفعنا شرّهم عنك؛ ففي هذا أنّ الله يكفي أولياءه شرَّ أعدائهم؛ فاطمئن إلى أنّ الله يكفيك شرَّ من عاداك إن كنت على الحقّ، فامضِ في دعوتك واثقًا بكفايته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["كفيناك المستهزئين"],"heart_state":{"text":"الاطمئنانُ إلى أنّ الله يكفي أولياءه شرَّ أعدائهم."},"action":{"text":"امضِ في الحقِّ واثقًا بأنّ الله يكفيك شرَّ من يستهزئ بك ويعاديك، فقد كفى نبيَّه المستهزئين، فمن كفاه الله لم يضرّه أحد."}},{"n":96,"reflection":{"text":"«الذين يجعلون مع الله إلها آخر فسوف يعلمون» — أولئك المستهزئون الذين يجعلون مع الله معبودًا آخر يشركون به، فسوف يعلمون عاقبةَ شركهم واستهزائهم حين يرون العذاب؛ ففي هذا وعيدٌ للمشركين المستهزئين؛ فاحذر الشركَ والاستهزاءَ بالحقّ، فعاقبتهما وخيمةٌ، والزم التوحيدَ وتعظيمَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الشركِ والاستهزاءِ بالحقّ، فعاقبتهما وخيمة."},"action":{"text":"احذر الشركَ بالله والاستهزاءَ بالحقّ وأهله، فعاقبةُ ذلك العذاب، والزم التوحيدَ الخالصَ وتعظيمَ الله وشعائره."}}]},{"title":"علاجُ ضيقِ الصدرِ بالتسبيحِ والعبادة","range":[97,99],"theme":"أنّ دواءَ ضيقِ الصدرِ التسبيحُ والسجودُ ودوامُ العبادةِ حتى الموت","verses":[{"n":97,"reflection":{"text":"«ولقد نعلم أنك يضيق صدرك بما يقولون» — ولقد نعلم يا محمد أنه يضيق صدرك بما يقوله المشركون من التكذيبِ والاستهزاءِ والطعن؛ ففي هذا مواساةُ الله لنبيّه بأنه يعلم ما يجده من الضيق؛ ففي هذا أنّ الله يعلم همومك ويواسيك؛ فاطمئن إلى أنّ الله يعلم ما يضيق به صدرك من أذى الناس، ويواسيك ويأجرك عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى أنّ الله يعلم همومَ عبده ويواسيه."},"action":{"text":"اطمئن إلى أنّ الله يعلم ما يضيق به صدرك من الهمِّ والأذى، ويواسيك ويأجرك، فاشكُ همّك إليه وحده وثق بعلمه بحالك."}},{"n":98,"reflection":{"text":"«فسبح بحمد ربك وكن من الساجدين» — فنزّه ربّك عمّا يقولون وسبّحه حامدًا له، وكن من المصلّين الساجدين له؛ ففي هذا أنّ دواءَ ضيقِ الصدرِ التسبيحُ والحمدُ والصلاة؛ فإذا ضاق صدرك بالهمومِ فالجأ إلى التسبيحِ والحمدِ والصلاةِ والسجود، فبها ينشرح الصدرُ وتزول الهموم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"علاجُ ضيقِ الصدرِ بالتسبيحِ والحمدِ والصلاةِ والسجود."},"action":{"text":"إذا ضاق صدرك بالهمومِ والأذى فالجأ إلى تسبيحِ الله وحمده والصلاةِ والسجود، فبها ينشرح الصدرُ وتطمئنّ النفس."}},{"n":99,"reflection":{"text":"«واعبد ربك حتى يأتيك اليقين» — واعبد ربّك ودُم على عبادته حتى يأتيك اليقينُ (الموتُ الذي هو متيقّنٌ آتٍ)؛ ففي هذا أنّ العبادةَ واجبةٌ إلى آخرِ لحظةٍ من العمر، وأنّ لا انقطاعَ لها إلا بالموت، وأنّ التكاليفَ لا تسقط ما دام العقلُ حاضرًا؛ فخُتمت السورةُ بالأمرِ بدوامِ العبادةِ حتى الموت؛ فداوم على عبادةِ ربّك ولا تنقطع عنها حتى يأتيك الموت، فالعبادةُ عمرٌ كلُّه لا موسمٌ ينقضي.","source":"تفسير السعدي","grade":"ma'thur"},"names":["حتى يأتيك اليقين"],"heart_state":{"text":"الاستمرارُ على عبادةِ الله حتى الموت، فلا انقطاعَ لها."},"action":{"text":"داوم على عبادةِ ربّك من صلاةٍ وذكرٍ وطاعةٍ حتى يأتيك الموت، فلا تنقطع عنها في صحّةٍ ولا سعة، فالعبادةُ عمرٌ كلُّه."}}]}],"coverage":{"covered":99,"total":99}};
